    const device = this._device();
    const size = this._displaySize(device);
    const object = this._selectedObject();
    const designerScreenWidth = Math.max(1, Math.round(size.width * this._zoom));
    const designerScreenHeight = Math.max(1, Math.round(size.height * this._zoom));
    const designerLarge400 = this._isLarge400Device(device);
    const designerFrameRatio = designerLarge400
      ? (this._orientation === "portrait" ? 898 / 1039 : 1039 / 898)
      : Math.max(0.48, Math.min(3.7, (size.width / size.height) * (this._orientation === "portrait" ? 0.95 : 1 / 0.95)));
    const designerFrameWidth = Math.max(150, Math.round(designerScreenWidth / (designerLarge400 ? (this._orientation === "portrait" ? 0.67 : 0.77) : (this._orientation === "portrait" ? 0.8 : 0.76))));
    const designerFrameRadius = Math.max(4, Math.min(28, Math.round(Math.min(designerFrameWidth, designerFrameWidth / designerFrameRatio) * 0.06)));
    const designerBattery = this._batteryInfo(device || {});
    const designerRssi = Number(device?.rssi);
